30	const PROCESSING_FEE = 5;
31	
32	/**
33	 * The spec keeps intermediate amounts as exact fractions and rounds only the
34	 * final amount. Binary floating point cannot do that: `100 * 1.1` is
35	 * 110.00000000000001, which rounds *up* to 111 instead of 110.
36	 *
37	 * So percentages are applied as integer rationals — multiply by the numerator
38	 * first, divide by the denominator last — and money is carried in hundredths
39	 * of a G. Both operands of every product stay integral, so no drift accrues.
40	 */
41	const SUBUNITS_PER_G = 100;
42	const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);
43	
44	/**
45	 * A modifier as an exact rational: the surcharge or discount *itself*, not the
46	 * multiplied total. +10 % is { num: 10, den: 100 }; a discount has a negative
47	 * numerator. Modifiers are summed onto a base, never multiplied through it.
48	 */
49	interface Rate {
50	  num: number;
51	  den: number;
52	}
53	
54	const FIRST_INSURANCE_SURCHARGE: Rate = { num: 10, den: 100 };
55	const CURSE_SURCHARGE: Rate = { num: 50, den: 100 };
56	const HIGH_ENCHANTMENT_SURCHARGE: Rate = { num: 30, den: 100 };
57	
58	/** An item is highly enchanted from this level upwards. */
59	const HIGH_ENCHANTMENT_LEVEL = 5;
60	
61	/** The modifier amount `rate` contributes against `subunits` — not the total. */
62	const rateAmount = (subunits: number, rate: Rate): number => (subunits * rate.num) / rate.den;
63	
64	/** Premiums round up — in the MHPCO's favour. */
65	const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);
66	
67	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
68	  sword: 100,
69	  amulet: 60,
70	  staff: 80,
71	  potion: 40,
72	  rune: 25,
73	  moonstone: 25,
74	};
75	
76	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type] ?? 0;
77	
78	const COMPONENT_TYPES = ["rune", "moonstone"];
79	
80	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
81	
82	/** Exactly this many alike components form a block, priced as one unit. */
83	const COMPONENT_BLOCK_SIZE = 3;
84	const COMPONENT_BLOCK_PREMIUM = 60;
85	
86	/** Splits items into those matching the predicate and those that do not. */
87	const partition = (items: Item[], matches: (item: Item) => boolean): [Item[], Item[]] => [
88	  items.filter(matches),
89	  items.filter((item) => !matches(item)),
90	];
91	
92	const groupByType = (items: Item[]): Map<string, Item[]> => {
93	  const groups = new Map<string, Item[]>();
94	  for (const item of items) groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
95	
96	  return groups;
97	};
98	
99	const sumOfBasePremiums = (items: Item[]): number =>
100	  items.reduce((total, item) => total + basePremiumOf(item), 0);
101	
102	/**
103	 * Alike components — those of the very same type — form a block when there are
104	 * exactly COMPONENT_BLOCK_SIZE of them; the block is priced as one unit.
105	 * Any other count is priced per component.
106	 */
107	const componentGroupPremium = (group: Item[]): number =>
108	  group.length === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : sumOfBasePremiums(group);
109	
110	/**
111	 * The policy base premium: every insured item's base premium, summed — except
112	 * that each group of alike components is priced as blocks where it can be.
113	 */
114	const policyBasePremiumOf = (items: Item[]): number => {
115	  const [components, mainItems] = partition(items, isComponent);
116	  const componentsTotal = [...groupByType(components).values()].reduce(
117	    (total, group) => total + componentGroupPremium(group),
118	    0,
119	  );
120	
121	  return sumOfBasePremiums(mainItems) + componentsTotal;
122	};
123	
124	/** The total the given rates contribute against a shared base. */
125	const sumOfRateAmounts = (base: number, rates: Rate[]): number =>
126	  rates.reduce((total, rate) => total + rateAmount(base, rate), 0);
127	
128	const isHighlyEnchanted = (item: Item): boolean =>
129	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
130	
131	/** Which item-specific modifiers an item attracts, by its own attributes. */
132	const ratesForItem = (item: Item): Rate[] => [
133	  ...(item.cursed ? [CURSE_SURCHARGE] : []),
134	  ...(isHighlyEnchanted(item) ? [HIGH_ENCHANTMENT_SURCHARGE] : []),
135	];
136	
137	/** Which policy-wide modifiers a policy attracts. */
138	const ratesForPolicy = (): Rate[] => [FIRST_INSURANCE_SURCHARGE];
139	
140	/** Item-specific modifiers apply to the affected item's own base premium. */
141	const itemModifiersOf = (items: Item[]): number =>
142	  items.reduce(
143	    (total, item) =>
144	      total + sumOfRateAmounts(toSubunits(basePremiumOf(item)), ratesForItem(item)),
145	    0,
146	  );
147	
148	/** Policy-wide modifiers apply to the policy base premium. */
149	const policyModifiersOf = (policyBase: number): number =>
150	  sumOfRateAmounts(policyBase, ratesForPolicy());
151	
152	/**
153	 * Modifiers are additive amounts, each computed against its own base: item
154	 * modifiers against the affected item, policy-wide modifiers against the
155	 * policy base premium. The processing fee is added at the very end.
156	 */
157	const quotePremium = (items: Item[]): number => {
158	  const policyBase = toSubunits(policyBasePremiumOf(items));
159	
160	  return toPremiumGold(
161	    policyBase +
162	      itemModifiersOf(items) +
163	      policyModifiersOf(policyBase) +
164	      toSubunits(PROCESSING_FEE),
165	  );
166	};
167	
168	export const runScenario = (scenario: Scenario): ScenarioResults => {
169	  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
170	};
